+				diags = diags.Append(n.validateImportTargetExpansion(to, imp.Config.To))
+				if diags.HasErrors() {
+					return diags
+				}
+				_, evalDiags = evaluateImportIdExpression(imp.Config.ID, ctx, keyData, true)
+				diags = diags.Append(evalDiags)
