// GraphNodeEvalable
func (n *NodeValidatableResource) Execute(ctx EvalContext, op walkOperation) (diags tfdiags.Diagnostics) {
	// this is done first since there may not be config if we are generating it
	diags = diags.Append(n.validateImportTargets(ctx))

	if n.Config == nil {
		return diags
	}

	diags = diags.Append(n.validateResource(ctx))

	keyData := EvalDataForNoInstanceKey
	selfAddr := n.ResourceAddr().Resource.Instance(addrs.NoKey)
	if n.Config.Count != nil {
		keyData = InstanceKeyEvalData{
			CountIndex: cty.UnknownVal(cty.Number),
		}
		selfAddr = n.ResourceAddr().Resource.Instance(addrs.IntKey(0))
	} else if n.Config.ForEach != nil {
		keyData = InstanceKeyEvalData{
			EachKey:   cty.UnknownVal(cty.String),
			EachValue: cty.DynamicVal,
		}
		selfAddr = n.ResourceAddr().Resource.Instance(addrs.StringKey(""))
	}

	for _, cr := range n.Config.Preconditions {
		var condRefs []*addrs.Reference
		for _, traversal := range cr.Condition.Variables() {
			ref, refDiags := addrs.ParseRef(traversal)
			diags = diags.Append(refDiags)
			if ref != nil {
				condRefs = append(condRefs, ref)
			}
		}
		condScope := ctx.EvaluationScope(nil, nil, keyData)
		condCtx, condCtxDiags := condScope.EvalContext(condRefs)
		diags = diags.Append(condCtxDiags)
		_, condValDiags := cr.Condition.Value(condCtx)
		diags = diags.Append(condValDiags)

		msgRefs, msgRefDiags := langrefs.ReferencesInExpr(addrs.ParseRef, cr.ErrorMessage)
		diags = diags.Append(msgRefDiags)
		msgScope := ctx.EvaluationScope(nil, nil, keyData)
		msgCtx, msgCtxDiags := msgScope.EvalContext(msgRefs)
		diags = diags.Append(msgCtxDiags)
		_, msgValDiags := cr.ErrorMessage.Value(msgCtx)
		diags = diags.Append(msgValDiags)
	}

	for _, cr := range n.Config.Postconditions {
		condRefs, condRefDiags := langrefs.ReferencesInExpr(addrs.ParseRef, cr.Condition)
		diags = diags.Append(condRefDiags)
		condScope := ctx.EvaluationScope(selfAddr, nil, keyData)
		condCtx, condCtxDiags := condScope.EvalContext(condRefs)
		diags = diags.Append(condCtxDiags)
		_, condValDiags := cr.Condition.Value(condCtx)
		diags = diags.Append(condValDiags)

		msgRefs, msgRefDiags := langrefs.ReferencesInExpr(addrs.ParseRef, cr.ErrorMessage)
		diags = diags.Append(msgRefDiags)
		msgScope := ctx.EvaluationScope(selfAddr, nil, keyData)
		msgCtx, msgCtxDiags := msgScope.EvalContext(msgRefs)
		diags = diags.Append(msgCtxDiags)
		_, msgValDiags := cr.ErrorMessage.Value(msgCtx)
		diags = diags.Append(msgValDiags)
	}

	diags = diags.Append(n.validateImportTargets(ctx))

	if managed := n.Config.Managed; managed != nil {
		for _, p := range managed.Provisioners {
			provisioner, err := ctx.Provisioner(p.Type)
			if err != nil {
				diags = diags.Append(err)
				return diags
			}
			if provisioner == nil {
				return diags.Append(fmt.Errorf("provisioner %s not initialized", p.Type))
			}
			provisionerSchema, err := ctx.ProvisionerSchema(p.Type)
			if err != nil {
				return diags.Append(fmt.Errorf("failed to read schema for provisioner %s: %s", p.Type, err))
			}
			if provisionerSchema == nil {
				return diags.Append(fmt.Errorf("provisioner %s has no schema", p.Type))
			}

			configVal, _, configDiags := ctx.EvaluateBlock(p.Config, provisionerSchema, selfAddr, keyData)
			diags = diags.Append(configDiags)
			if configVal == cty.NilVal {
				return diags.Append(fmt.Errorf("EvaluateBlock returned nil value"))
			}

			unmarkedConfigVal, _ := configVal.UnmarkDeep()
			resp := provisioner.ValidateProvisionerConfig(provisioners.ValidateProvisionerConfigRequest{
				Config: unmarkedConfigVal,
			})
			diags = diags.Append(resp.Diagnostics)

			if p.Connection != nil {
				cfg := p.Connection.Config
				if baseConn != nil {
					cfg = configs.MergeBodies(baseConn.Config, cfg)
				}
				_, _, connDiags := ctx.EvaluateBlock(cfg, connectionBlockSupersetSchema, selfAddr, keyData)
				diags = diags.Append(connDiags)
			} else if baseConn != nil {
				_, _, connDiags := ctx.EvaluateBlock(baseConn.Config, connectionBlockSupersetSchema, selfAddr, keyData)
				diags = diags.Append(connDiags)
			}
			if diags.HasErrors() {
				return diags
			}
		}
	}
	return diags
}

