package terraform

import (
	"testing"

	"github.com/hashicorp/terraform/internal/addrs"
	"github.com/hashicorp/terraform/internal/providers"
	"github.com/hashicorp/terraform/internal/states"
)

func TestTmpValidateImportBlockIssue35543(t *testing.T) {
	m := testModuleInline(t, map[string]string{
		"main.tf": `
resource "null_resource" "undef-local" {
}

resource "null_resource" "undef-var" {
}

import {
  to = null_resource.undef-local
  id = local.something_not_defined
}

import {
  to = null_resource.undef-var
  id = var.some_other_undefined_thing
}

import {
    to = null_resource.not-a-real-resource
    id = "blah"
}
`,
	})

	p := simpleMockProvider()
	ctx := testContext2(t, &ContextOpts{
		Providers: map[addrs.Provider]providers.Factory{
			addrs.NewDefaultProvider("null"): testProviderFuncFixed(p),
		},
	})

	diags := ctx.Validate(m, &ValidateOpts{})
	if !diags.HasErrors() {
		t.Fatal("expected errors, got none")
	}
	t.Logf("diags:\n%s", diags.Err())

	// a valid config must still pass
	m2 := testModuleInline(t, map[string]string{
		"main.tf": `
resource "null_resource" "a" {
}

import {
  to = null_resource.a
  id = "blah"
}
`,
	})
	ctx2 := testContext2(t, &ContextOpts{
		Providers: map[addrs.Provider]providers.Factory{
			addrs.NewDefaultProvider("null"): testProviderFuncFixed(p),
		},
	})
	diags = ctx2.Validate(m2, &ValidateOpts{})
	if diags.HasErrors() {
		t.Fatalf("unexpected errors: %s", diags.Err())
	}

	_, planDiags := ctx2.Plan(m2, states.NewState(), DefaultPlanOpts)
	if planDiags.HasErrors() {
		t.Fatalf("unexpected plan errors: %s", planDiags.Err())
	}
}

